def panel(pre):
    r=read(D/(pre+"results.json"))
    labels={"base":"Первый просмотр", "right":"Вправо", "left":"Влево", "both":"По 128 на сторону", "line_neighbors":"Соседние целые строки", "scope_neighbors":"Соседи в AST-границах", "lexical":"Одна сторона по словам запроса", "index":"Переход по второму максимуму BM25", "equal_both":"Обе стороны, точная цена", "equal_right":"Вправо, точная цена"}
    out=["| Выдача | Recall всех строк, % | Полная цель, % | Хотя бы одна, % | Recall новых строк, % | Расход, WP |","|---|---:|---:|---:|---:|---:|"]
    for arm,label in labels.items():
        if arm not in r["outcomes"]:continue
        v=r["outcomes"][arm]
        out.append(f"| {label} | {100*v['recall']:.2f} | {100*v['all']:.2f} | {100*v['any']:.2f} | {100*v['new_recall']:.2f} | {v['tokens']:.2f} |")
    return "\n".join(out)
